const fs = require('fs');
const { chromium } = require('playwright');

(async () => {
  const vendorJs = fs.readFileSync('/app/vendor/infographic.min.js', 'utf8');
  const html = `<!doctype html><html><head><meta charset="utf-8" />
  <style>
    html, body { margin:0; padding:0; width:100%; height:100%; background:#0b1220; }
    #container { width:100%; height:100%; }
  </style>
  </head><body>
  <div id="container"></div>
  <script>
  ${vendorJs}
  </script>
  <script>
    window.__LOGS__ = [];
    window.__READY__ = false;
    try {
      window.__LOGS__.push('AntVInfographic=' + (typeof window.AntVInfographic));
      const infographic = new AntVInfographic.Infographic({ container: '#container', width: '100%', height: '100%' });
      const syntax = "infographic chart-bar-plain-text\n"+
        "data\n"+
        "  title Test\n"+
        "  values\n"+
        "    - label A\n"+
        "      value 10\n"+
        "    - label B\n"+
        "      value 20\n"+
        "theme\n"+
        "  palette #0ea5e9 #22c55e #a855f7";
      infographic.render(syntax);
      window.__READY__ = true;
      window.__LOGS__.push('rendered');
    } catch (e) {
      window.__READY__ = true;
      window.__LOGS__.push('exception: '+String(e));
    }
  </script>
  </body></html>`;

  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 900, height: 1200 }, deviceScaleFactor: 2 });
  page.on('pageerror', (err) => console.log('PAGEERROR:', err.toString()));
  await page.setContent(html, { waitUntil: 'load' });
  await page.waitForTimeout(1500);
  const logs = await page.evaluate(() => window.__LOGS__);
  console.log('logs', logs);
  await page.screenshot({ path: '/app/output/render_test.png', type: 'png' });
  await browser.close();
})();
