            <div class="bigStat">
              <div class="bigNumber">${globalUsers}</div>
              <div class="bigLabel">Global internet users (2025)</div>
            </div>
            <div class="supportRow">
              <div class="pill">Global penetration: <b style="color:var(--ink)">${globalPen}</b></div>
              <div class="pill">Avg. daily social media: <b style="color:var(--ink)">${socialMinutes} min</b></div>
            </div>
            <div class="noteSmall">Source brief: 2025 estimates; values rounded for readability.</div>
          </div>

          <div class="callouts">
            <div class="callout primary">
              <div class="label">China — Online Population</div>
              <div class="value">${chinaUsers}</div>
              <div class="note">Largest digital population; ~76% penetration.</div>
            </div>
            <div class="callout secondary">
              <div class="label">India — Online Population</div>
              <div class="value">${indiaUsers}</div>
              <div class="note">Massive growth runway; ~62% penetration.</div>
            </div>
          </div>
        </section>

        <section class="main">
          <div class="card" style="padding:44px 54px;">
            <div class="sectionTitle">
              <h2>Internet Penetration Rates by Country</h2>
              <div class="hint">% of population online • ranked</div>
            </div>
            <div class="bars">
              ${penetrationRows}
            </div>
            <div class="noteSmall">Selected major digital economies from the brief; penetration shown as %.</div>
          </div>

          <div class="mini">
            <div class="miniCard">
              <h3>The World's Digital Population</h3>
              <div class="sub">Top countries by estimated online population (2025).</div>
              <div class="popBars">
                ${popRows}
              </div>
            </div>

            <div class="miniCard">
              <h3>How People Spend Time Online</h3>
              <div class="sub">Largest social platforms by monthly active users.</div>
              <div class="platforms">
                ${platformRows}
              </div>
            </div>
          </div>
        </section>

        <footer>
          <div class="takeaway">
            <div class="kicker">Economic takeaway</div>
            <div class="bigStat" style="margin-top:12px;">
              <div class="bigNumber">${ecommerce}</div>
              <div class="bigLabel">Projected global retail e-commerce sales by 2027</div>
            </div>
            <div class="noteSmall">Connectivity scale → market scale: digital access enables commerce, services, and AI-enabled growth.</div>
          </div>
          <div class="sources">
            <h3>Sources (provided)</h3>
            <ul>
              <li><code>/app/benchmark/source_brief.md</code> — country penetration, online population, platforms, economy notes.</li>
              <li><code>/app/benchmark/task_input.json</code> — poster goals, sections, key metrics.</li>
            </ul>
            <div class="noteSmall">Poster generated automatically for a data-report audience.</div>
          </div>
        </footer>

      </div>
    </div>
  </body></html>`;

  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: A1_PX.width, height: A1_PX.height }, deviceScaleFactor: 1 });
  await page.setContent(html, { waitUntil: 'load' });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: '/app/output/final_poster.png', type: 'png' });
  await browser.close();

  console.log('Wrote /app/output/final_poster.png');
})();
